#[tokio::main]
async fn main() -> anyhow::Result<()> {
    use rig::memory::{MemoryStore, load};
    use rig::providers::openai::{self, OpenAI};
    let store = MemoryStore::default();
    let agent = rig::AgentBuilder::new(OpenAI::from_env()?.completion(openai::GPT_5_5))
        .preamble("You are a helpful assistant.")
        .memory(store.clone()).build();
    agent.prompt("My name is Ada.").conversation("user-42").await?;
    let reply = agent.prompt("What's my name?").conversation("user-42").await?;
    println!("{}", reply.output());
    assert_eq!(load(&store, "user-42")?.messages().len(), 4);
    Ok(())
}

use rig::memory::{MemoryStore, load, save};
use rig::message::Message;

fn main() -> anyhow::Result<()> {
    // Store / AsyncStore replace ConversationMemory. load/save manage session format.
    let store = MemoryStore::default();
    let mut conversation = load(&store, "user-42")?;
    conversation.extend([Message::user("My name is Ada."), Message::assistant("Hello, Ada!")]);
    save(&store, "user-42", &mut conversation)?;
    let resumed = load(&store, "user-42")?;
    assert_eq!(resumed.messages(), conversation.messages());
    println!("saved and restored {} messages", resumed.messages().len());
    Ok(())
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    use rig::memory::{MemoryStore, load, save};
    use rig::memory::recent::{view, LastMessages};
    use rig::providers::openai::{self, OpenAI};
    let store = MemoryStore::default();
    let mut conversation = load(&store, "user-42")?;
    let selected = view(conversation.messages(), &LastMessages(20)).to_vec();
    let agent = rig::AgentBuilder::new(OpenAI::from_env()?.completion(openai::GPT_5_5)).build();
    // Restrict only the request window; retain the full stored conversation.
    let response = agent.prompt("Hello!").history(selected).await?;
    println!("{}", response.output());
    conversation.extend(response.messages);
    save(&store, "user-42", &mut conversation)?;
    Ok(())
}

